CREATE TABLE public.network_agreement_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),referral_id uuid NOT NULL REFERENCES public.network_referrals(id) ON DELETE CASCADE,owner_id uuid NOT NULL REFERENCES public.profiles(id),realtor_id uuid NOT NULL REFERENCES public.profiles(id),recorded_by uuid NOT NULL REFERENCES public.profiles(id),reference text NOT NULL,created_at timestamptz NOT NULL,archived_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.network_agreement_history TO authenticated; GRANT ALL ON public.network_agreement_history TO service_role; ALTER TABLE public.network_agreement_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY network_agreement_history_parties ON public.network_agreement_history FOR SELECT TO authenticated USING(public.network_eligible(auth.uid()) AND (owner_id=auth.uid() OR realtor_id=auth.uid()) AND EXISTS(SELECT 1 FROM public.network_referrals r WHERE r.id=referral_id AND NOT r.hidden));
CREATE FUNCTION public.network_archive_agreement() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF OLD.selected_realtor_id IS DISTINCT FROM NEW.selected_realtor_id AND OLD.selected_realtor_id IS NOT NULL THEN INSERT INTO public.network_agreement_history(referral_id,owner_id,realtor_id,recorded_by,reference,created_at) SELECT OLD.id,OLD.owner_id,OLD.selected_realtor_id,a.recorded_by,a.reference,a.created_at FROM public.network_agreements a WHERE a.referral_id=OLD.id; DELETE FROM public.network_agreements WHERE referral_id=OLD.id; END IF; RETURN NEW; END; $$;
CREATE TRIGGER network_archive_agreement_before_reselection BEFORE UPDATE OF selected_realtor_id ON public.network_referrals FOR EACH ROW EXECUTE FUNCTION public.network_archive_agreement();
REVOKE ALL ON FUNCTION public.network_archive_agreement() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.network_members(p_ids uuid[]) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.network_eligible(auth.uid()) AND NOT public.is_admin() THEN RAISE EXCEPTION 'A Realtor license number on file is required'; END IF; RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',p.id,'first_name',p.first_name,'last_name',p.last_name,'avatar_url',p.avatar_url,'brokerage_name',p.brokerage_name,'markets',p.markets,'counties',p.counties,'services',p.services,'license_number',p.license_number,'license_state',p.license_state,'experience_history',p.experience_history,'cities',coalesce(n.cities,'{}'),'zip_codes',coalesce(n.zip_codes,'{}'),'primary_market',n.primary_market,'specialties',coalesce(n.specialties,'{}'),'credentials',n.credentials)) FROM public.profiles p LEFT JOIN public.network_profiles n ON n.user_id=p.id WHERE p.id=ANY(p_ids) AND p.role='realtor' AND (p.id=auth.uid() OR public.is_admin() OR EXISTS(SELECT 1 FROM public.network_referrals r WHERE r.owner_id=p.id AND public.network_can_read(r.id)) OR EXISTS(SELECT 1 FROM public.network_responses x WHERE x.realtor_id=p.id AND public.network_thread_access(x.id)))),'[]'::jsonb); END; $$;